extern RealGLFunctions g_real;

// getProcFn: typically wglGetProcAddress (only valid with a current context;
// returns null for GL1.1 core functions, which are resolved from moduleHandle instead).
void LoadRealGLFunctions(void* moduleHandle, void* (*getProcFn)(const char*));

// Assigns g_real.<name> = addr for whichever known function `name` is --
// used by the IAT patcher (for statically-imported names) and by the
// hooked wglGetProcAddress (for extension names resolved at runtime).
// No-op if `name` isn't one of the known functions.
void StoreRealPointer(const char* name, void* addr);

